"""Отчет ЛР2-3, часть 2: воронка, поиск, платежеспособность, сведение, цели проекта, чувствительность, вопросы, выводы, источники, приложения."""
import rep_common as C
from rep_common import H, P, num, pct, table, figure, A, X
from inputs import *

sw = load_sw()
OB = X["ob"]; PC = X["pc"]; TB = X["tb"]; PAYX = X["pay"]; FUN = X["fun"]; SCX = X["sc"]; SE = X["se"]
ARP = {sc: arppu(sc) for sc in SC}
G = A["goal"]
SEARCH_SOM = X["fun"]["channels"][1][5] / FUNNEL["cover"] * 12 * FUNNEL["reach"]["base"] * FUNNEL["v2l"]["base"] * FUNNEL["l2p"]["base"] * ARP["base"][0]
FIN = A["final_potential"]
eur = lambda v, d=0: num(v, d) + " EUR"


def run():
    # ---------------- 2.7
    H(3, "2.7 Цифровая воронка по тарифам и канал AppSource")
    P("Воронка TableMind построена по пути пользователя: визит на сайт, регистрация в тарифе Free, первый аудит, затем переход в платящие тарифы: разовый аудит 9 EUR, Pro 19 EUR в месяц, Team 29 EUR за место (со следующего релиза). Исходный трафик - полный релевантный трафик сегмента из раздела 2.3; достижимая доля трафика для нового сайта принята 0,5 %, 1,5 % и 4 % (допущение Д-12) с учетом того, что канал строится с нуля.")
    mix = MIX["base"]["share"]; ev = MIX["base"]["events"]
    pm = G["base"]["payers_month"]
    rows = []
    for nm, sh, e, price in (("Разовый аудит", mix[0], ev[0], PRICE["audit"]), ("Pro", mix[1], ev[1], PRICE["pro"]), ("Team (место)", mix[2], ev[2], PRICE["team"])):
        rows.append([f"{nm} ({num(price, 0)} EUR)", pct(sh, 0), num(pm * sh, 2), num(e, 1), num(price * e, 1), num(pm * sh * price * e, 1)])
    rows.append(["Итого", "100 %", num(pm, 2), num(ARP["base"][1], 2), num(ARP["base"][0], 2), num(pm * ARP["base"][0], 1)])
    table("tariffs", "Платящие и выручка по тарифам, базовый сценарий, в месяц",
          ["Тариф", "Доля", "Платящих в месяц", "Платежей в год", "Выручка первого года на платящего, EUR", "Выручка в месяц, EUR"],
          rows,
          f"В базовом сценарии воронка дает {num(FUN['funnel']['base'][6], 1)} платящих в месяц при {num(FUN['funnel']['base'][4], 0)} регистрациях в месяц; средняя выручка первого года на платящего - {eur(ARP['base'][0], 1)} (осторожный {eur(ARP['cons'][0], 1)}, оптимистичный {eur(ARP['opt'][0], 1)}). Структура платящих и число платежей - допущение Д-09: доля Pro и Team задает основную выручку, разовые аудиты дают мало.")
    table("funnel", "Цифровая воронка TableMind по сценариям, в месяц",
          ["Этап", "Осторожный", "Базовый", "Оптимистичный"],
          [["Полный релевантный трафик сегмента, визитов", num(FUN["funnel"]["cons"][0]), num(FUN["funnel"]["base"][0]), num(FUN["funnel"]["opt"][0])],
           ["Достижимая доля трафика", pct(FUNNEL["reach"]["cons"], 1), pct(FUNNEL["reach"]["base"], 1), pct(FUNNEL["reach"]["opt"], 1)],
           ["Визитов на сайт TableMind", num(FUN["funnel"]["cons"][2]), num(FUN["funnel"]["base"][2]), num(FUN["funnel"]["opt"][2])],
           ["Регистраций Free", num(FUN["funnel"]["cons"][4], 1), num(FUN["funnel"]["base"][4], 1), num(FUN["funnel"]["opt"][4], 1)],
           ["Новых платящих", num(FUN["funnel"]["cons"][6], 2), num(FUN["funnel"]["base"][6], 2), num(FUN["funnel"]["opt"][6], 2)],
           ["Годовая выручка новых платящих (по шаблону, EUR)", num(FUN["funnel"]["cons"][9]), num(FUN["funnel"]["base"][9]), num(FUN["funnel"]["opt"][9])],
           ["Годовая выручка с платежами в течение года (LTV-лист, EUR)", num(FUN["ltv"]["cons"][3]), num(FUN["ltv"]["base"][3]), num(FUN["ltv"]["opt"][3])]],
          f"Воронка показывает, что рост ограничен верхней частью: даже при {num(FUN['funnel']['base'][2])} визитах в месяц в базовом сценарии платящих менее пяти в месяц. Лист шаблона, где выручка равна продажам на единичный чек, занижает результат, поэтому для сопоставления использован лист повторных платежей: {eur(FUN['ltv']['base'][3])} в год против {eur(FUN['funnel']['base'][9])} по простой формуле.")
    P(f"Канал AppSource оценен листом платформенной модели: при 2, 8 и 20 оплатах в месяц и комиссии магазина 3 % (допущение Д-14, условия Microsoft ДОСНЯТЬ) оборот через магазин равен {eur(FUN['gmv']['cons'][2])}, {eur(FUN['gmv']['base'][2])} и {eur(FUN['gmv']['opt'][2])} в год, комиссия - {eur(FUN['gmv']['base'][1] * 12)} в базовом сценарии. Канал дешевый по комиссии, но не заменяет основной трафик: его вклад зависит от видимости надстройки в магазине, которой пока нет. Данные об AppSource (число надстроек, отзывы) в этой работе не собирались и вынесены в приложение Б.")

    # ---------------- 2.8
    H(3, "2.8 Поисковый спрос: контрольный русскоязычный сегмент")
